import java.util.Scanner;

interface Priced {
    int TAX = 10;
    String UNIT = "円";

    int price();
}

class Book implements Priced {
    private int base;
    private int count;

    Book(int base, int count) {
        this.base = base;
        this.count = count;
    }

    @Override
    public int price() {
        return base * count;
    }

    String label() {
        return "本 " + price() + UNIT;
    }
}

class Ticket implements Priced {
    private int base;

    Ticket(int base) {
        this.base = base;
    }

    @Override
    public int price() {
        return base;
    }

    String label() {
        return "券 " + price() + UNIT;
    }
}

public class Main {

    static int taxOf(Priced item) {
        return item.price() * Priced.TAX / 100;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        for (int i = 0; i < k; i++) {
            String type = sc.next();
            if (type.equals("B")) {
                int base = sc.nextInt();
                int count = sc.nextInt();
                Book b = new Book(base, count);
                System.out.println(b.label() + " 税 " + taxOf(b) + Priced.UNIT);
            } else {
                int base = sc.nextInt();
                Ticket t = new Ticket(base);
                System.out.println(t.label() + " 税 " + taxOf(t) + Priced.UNIT);
            }
        }

        System.out.println("税率 " + Priced.TAX + "%");
    }
}

