    String fly();
}

interface Swimmable {
    String swim();
}

class Duck implements Flyable, Swimmable {
    private String name;
    Duck(String name) { this.name = name; }
    @Override public String fly()  { return name + "は飛ぶ"; }
    @Override public String swim() { return name + "は泳ぐ"; }
}

class Fish implements Swimmable {
    private String name;
    Fish(String name) { this.name = name; }
    @Override public String swim() { return name + "は泳ぐ"; }
}

public class Main {
    public static void main(String[] args) {
        Swimmable[] swimmers = { new Duck("カモ"), new Fish("コイ") };

