    public String train() {
        return name + "は研修を企画";
    }
}

class Senior extends Employee implements Trainable {
    Senior(String name, int salary) {
        super(name, salary);
    }

    @Override
    String role() {
        return "先輩";
    }

    @Override
    public String train() {
        return name + "は研修を担当";
    }
}

class Staff extends Employee {
    Staff(String name, int salary) {
        super(name, salary);
    }

    @Override
    String role() {
        return "一般";
    }
}

