        int k = sc.nextInt();
        Employee[] list = new Employee[k];

        for (int i = 0; i < k; i++) {
            String type = sc.next();
            String name = sc.next();
            int salary = sc.nextInt();
            if (type.equals("M")) {
                list[i] = new Manager(name, salary);
            } else if (type.equals("E")) {
                list[i] = new Senior(name, salary);
            } else {
                list[i] = new Staff(name, salary);
            }
        }

        int sum = 0;
        int count = 0;

        for (Employee e : list) {
            int pay = e.salary;
            if (e instanceof Bonusable b) {
                pay += b.bonus();
            }
            System.out.println(e.name + " " + e.role() + " 支給 " + pay);
